import type { BlogPostBodies } from "../types";

export const BLOG_POST_BODIES_BATCH_10: BlogPostBodies = {
  "gokarna-beach-trek-coastal-hopping-guide": [
    { "type": "p", "text": "Most Indian treks climb mountains. This one follows the sea. Between the fishing town of Gokarna and the cliffs of the Karnataka coast runs a trail that hops five beaches in a single day — forest paths giving way to rocky headlands, each headland dropping you onto another crescent of sand. The Gokarna beach trek is not a summit to bag. It is a slow coastal conversation, and it is the single best reason to visit Gokarna between October and March." },
    { "type": "h2", "text": "The five beaches, in trekking order" },
    { "type": "p", "text": "The classic route runs north to south, starting near the town and walking away from the crowds. Each beach has a distinct character, and the trek's pleasure is in how they change — from pilgrim-busy to backpacker-casual to properly wild." },
    { "type": "ul", "items": ["Gokarna Main Beach — the starting point, next to the Mahabaleshwar Temple. Pilgrims, fishing boats, a working shoreline rather than a postcard one. Grab breakfast at a town eatery before setting off.", "Kudle Beach — a 20–30 minute walk over the first headland. A wide crescent with beachfront cafés, yoga mats at sunrise and the best sunset of the five beaches. Many trekkers make this their base.", "Om Beach — named for its Om-shaped shoreline when seen from above. The liveliest of the five: banana boat rides, kayaking, shacks, and Namaste Café, the trail's most famous pit stop for pizza and cold drinks.", "Half Moon Beach — the crowd thins here. A small crescent tucked between two headlands, reached by a rocky cliff path. Quiet shacks, hammocks, clean sand and some of the coast's best sunset photography.", "Paradise Beach — the last and most secluded, reachable only on foot or by boat. Golden sand, almost nobody, and the classic overnight-camping and stargazing spot at the end of the trail."] },
    { "type": "h2", "text": "How long the trek takes and how hard it is" },
    { "type": "p", "text": "The full trail is roughly 8–10 kilometres and takes most walkers 4–6 hours including photo stops, a swim break and lunch at an Om Beach shack. The difficulty is easy to moderate: there are no technical sections, but the stretches between Om, Half Moon and Paradise cross rocky, uneven headlands that demand sturdy shoes and sure footing. Beginners do it comfortably every day of the season. Local guides at [Gokarna Tour Guide's trek page](https://gokarnatourguide.com/blogs/beach-hopping-gokarna-trek/) break the day into five segments — Main to Kudle in 20–30 minutes, Kudle to Om in about 30, Om to Half Moon in 30, and Half Moon to Paradise in 30–45 — which matches what most trekkers report on the ground." },
    { "type": "h2", "text": "Tide, trail and safety rules" },
    { "type": "p", "text": "This is a wild coastline, and three rules separate a good day from a bad one. First, start early — 7–8 AM — so you finish the rocky stretches in daylight and avoid the midday heat. Second, check the tide and the season: the trail is at its best October to March, and the monsoon months of July to September turn the cliff paths slippery and dangerous, so skip the trek then. Third, carry more water than you think you need — the headlands have no shops — and never swim alone off Paradise or Half Moon, where currents run stronger than they look. There is no entry fee and no permit required; the trail is open to all. If you would rather not walk back, local boats run between the beaches and can ferry you from Paradise back to Kudle or Om for a small fare." },
    { "type": "h2", "text": "How to reach Gokarna" },
    { "type": "p", "text": "Gokarna sits on the Konkan railway line, so trains are the easiest option. The nearest stations are Gokarna Road (GOK), about 10 km from town, and Ankola, about 20 km away — autos and buses connect both to the beaches. By air, the nearest airport is Dabolim in Goa, roughly 140–155 km north, a 3–3.5 hour drive south down the coast. Hubli airport is a similar distance inland. From Bengaluru, overnight KSRTC and private buses reach Gokarna in 9–10 hours, and organised weekend treks leave the city on Friday evenings and return Sunday night, trek included." },
    { "type": "h2", "text": "Best time for the beach trek" },
    { "type": "p", "text": "October to March is the season: dry weather, calm seas, clear skies and all five beach shacks open. November to February is the sweet spot — pleasant walking temperatures and the best sunsets. April to June is hot but quiet and still walkable if you start at dawn. Avoid July to September entirely; the monsoon closes the trail's safe window, and several sources including the detailed [Gokarna trek route guide](https://www.luxurytrailsofindia.com/blog/gokarna-beach-trek-guide/) advise against trekking in the rains." },
    { "type": "h2", "text": "Where to stay and what the trek costs" },
    { "type": "p", "text": "The trek itself is free — you only pay for food, stays and transport. Kudle Beach has the most trekkers' accommodation, from cliffside hostels like Zostel to budget shacks and mid-range resorts. Beachside camping near Kudle or Om is the classic overnight option. If you want it fully organised, operators like goChaarana run 2-day Gokarna trek weekends from Bengaluru, covering transport, a trek lead, campsite stay with bonfire and usually a backwater boat ride on day two. A DIY weekend — buses, beach shacks and café meals — costs far less and suits most budgets comfortably." },
    { "type": "h2", "text": "Extending the trip: the temple town, Mirjan Fort and Honnavar" },
    { "type": "p", "text": "The trek is a day; Gokarna deserves two. Spend the second morning at the Mahabaleshwar Temple, one of Karnataka's most revered Shiva shrines, home to the Atmalinga — the temple is why Gokarna town exists, and the contrast between the pilgrim crowds at dawn and the empty beaches by afternoon is the town's essential duality. Dress modestly and be prepared for queues during festivals; non-Hindus may have restricted access to the inner sanctum, as at many traditional temples." },
    { "type": "p", "text": "Then drive 20 km inland to Mirjan Fort, a 16th-century laterite fortress built under Queen Chennabhairadevi of Gersoppa, once the centre of the region's pepper trade. Its high walls, secret passages and rain-fed greenery make it the coast's best non-beach hour, and it is far less visited than it should be. On the way back toward the coast, Honnavar's backwaters — included in several organised Gokarna weekend itineraries — offer calm boat rides through mangrove channels, a gentle counterpoint to the previous day's cliff walking. Three days, two nights: trek, temple, fort, backwater. That is the complete Gokarna." },
    { "type": "h2", "text": "Frequently Asked Questions" },
    { "type": "h3", "text": "Can beginners do the Gokarna beach trek?" },
    { "type": "p", "text": "Yes. It is one of India's easiest multi-beach treks — roughly 8–10 km over 4–6 hours with basic fitness. The rocky headlands between Om, Half Moon and Paradise need good shoes, but there is nothing technical." },
    { "type": "h3", "text": "Which direction should I trek — north to south or the reverse?" },
    { "type": "p", "text": "North to south (Main Beach toward Paradise) is the classic order and ends at the most beautiful beach, perfect for an evening camp. Starting at Belekan, south of Paradise, and walking north to Kudle is equally popular with organised groups." },
    { "type": "h3", "text": "Is camping allowed on Paradise Beach?" },
    { "type": "p", "text": "Overnight camping at Paradise is a long-standing trekker tradition, but it is informal — carry everything in and out, keep noise down, and check current local guidance before planning a night there." },
    { "type": "h3", "text": "Can I do the trek in one day from Goa?" },
    { "type": "p", "text": "It is a long day. Dabolim is 3–3.5 hours each way, so a day trip means leaving before dawn. A one-night stay in Gokarna makes the trek far more enjoyable." }
  ],
  "tarkarli-malvan-diving-sindhudurg-guide": [
    { "type": "p", "text": "Maharashtra has one coast where the water is clear enough to see the reef. At Tarkarli, 8 km south of the fishing town of Malvan, the Arabian Sea turns a blue that surprises first-timers — and below it sits Maharashtra's only real scuba and snorkelling coast. Add the sea fort of Sindhudurg rising off the shore, dolphins at dawn, and Malvani fish curry on land, and you have the Konkan coast's best adventure weekend." },
    { "type": "h2", "text": "Scuba diving at Tarkarli: what to expect" },
    { "type": "p", "text": "The diving season runs October to May, when the sea is calm and visibility is at its best; the activity shuts down before the monsoon arrives in June. You do not need to know swimming — certified instructors train you in shallow water first, then take you down with them. Typical dives reach 10–20 metres, with coral beds, angelfish, parrotfish, butterfly fish and the occasional turtle or eel. The minimum age is 10 years, with an adult accompanying children. A single introductory dive is affordably priced by Indian standards — confirm exactly what the package includes (training, equipment, instructor, boat) before paying, as pricing varies by operator and season. Diving windows generally run from about 9:30 AM to 12:30 PM at the popular operators, so book the morning slot and arrive early — the [Tarkarli scuba diving season and cost guide](https://www.konkan.me/tarkarli-scuba-diving-konkan/) at Devbaug beach is the most detailed local reference for what is included." },
    { "type": "h2", "text": "Snorkelling: Tarkarli's easier prize" },
    { "type": "p", "text": "If scuba feels like too much, snorkelling is Tarkarli's easier prize. The shallow reef patches off the coast hold plate, white and cabbage corals and schools of glass, parrot, zebra and snapper fish — enough colour to fill a GoPro memory card in an hour. DNA's long-standing Tarkarli report calls it Maharashtra's only snorkelling haven, and the winter months of October to December bring the clearest water. Combine it with a morning dolphin-spotting boat: dolphins are regularly sighted at dawn, though no honest operator guarantees them." },
    { "type": "h2", "text": "The Sindhudurg Fort boat trip" },
    { "type": "p", "text": "A kilometre off the Malvan shore rises Sindhudurg Fort, built by Chhatrapati Shivaji in 1664 on the rocky Kurte island. Boats leave from the Malvan jetty — the ride itself is part of the experience, with the fort walls growing out of the sea as you approach. Inside are temples, the famous footprint of Shivaji, and rampart walks with 360-degree sea views. Boats run through the day in season; the fort trip pairs naturally with a morning dive, since both operate out of Malvan. Carry water and sun protection — there is little shade on the island." },
    { "type": "h2", "text": "Malvan town: the base for your weekend" },
    { "type": "p", "text": "Stay in Malvan town or along Tarkarli's beach road — MTDC's resort and a string of homestays and family-run resorts line the coast. The real draw on land is the food: Malvani cuisine means solkadhi, fried surmai, bombil fry and the fiery red curries of the Konkan. Tsunami Island, in the Karli backwaters, is the water-sports hub for parasailing, banana boats and jet skis if you want a full adventure day. The [DNA snorkelling and fort feature](https://www.dnaindia.com/lifestyle/report-tarkarli-the-only-snorkelling-haven-in-maharashtra-1908066) remains a good primer on how the town, the backwaters and the reef fit together." },
    { "type": "h2", "text": "How to reach Tarkarli and Malvan" },
    { "type": "p", "text": "From Mumbai it is roughly an 8-hour drive down the coast — a classic Friday-night departure, weekend-on-the-water plan for Mumbaikars and Punekars. By train, take the Konkan railway to Kudal station, then a bus to Malvan and a short bus or rickshaw ride on to Tarkarli. The nearest airport is Sindhudurg (Chipi), about 30 km from Malvan, with Dabolim in Goa the backup option for wider connections. Once there, autos and local taxis handle the short hops between Malvan jetty, Tarkarli beach and Devbaug." },
    { "type": "h2", "text": "Best time and honest caveats" },
    { "type": "p", "text": "October to May is the diving and snorkelling window, with October to March the most reliable for visibility. Monsoon (June to September) is a hard no — the sea is rough and operators shut down. Two honest caveats before you book: verify your dive operator's certification and equipment on the spot rather than trusting a listing, and treat dolphin sightings as a bonus, not a promise. Visibility varies with wind and recent rain even in season, so build one buffer day into a dive-focused trip." },
    { "type": "h2", "text": "Beyond the reef: Devbaug, Tsunami Island and the backwaters" },
    { "type": "p", "text": "The reef is the headline, but the Karli backwaters are the second act. Devbaug beach, where the Karli river meets the sea, is where many of Tarkarli's dive operators actually run their sessions — the water here is calmer and the training beaches are better sheltered. From Devbaug, boats cross to Tsunami Island, the sandbar in the backwaters that has become the region's water-sports hub: parasailing, banana boats, jet skis and kayaking, all in flat protected water that suits first-timers and families." },
    { "type": "p", "text": "If you have a second day, drive the coast south to Nivati and Vengurla — two of the Konkan's least developed beaches, all casuarina trees and empty sand, with a local market at Vengurla that regulars compare to a miniature Crawford Market. Dolphin boats leave at dawn from both Tarkarli and Devbaug; the early slot doubles your chances and gets you back for breakfast. The honest framing from every experienced operator holds: the reef and the fort are near-certain, the dolphins are a gift. Plan the trip around the certainties and let the dolphins be the bonus." },
    { "type": "p", "text": "A practical dive-day timeline: breakfast at your Tarkarli homestay or resort by 7:30 AM, reach the dive centre by 8:30 for the briefing and gear fitting, boat out by 9:30, first dive at 10, surface interval and lunch on the boat or beach, optional second dive or snorkel session by 2 PM, back on shore by 4. Most Tarkarli dive operators bundle gear, boat, instructor and a certificate-bearing fun dive into one package — confirm exactly what is included before you pay, and ask to see the instructor's certification card if you are doing your first dive. Stay options cluster along the Tarkarli–Devbaug beach road: family-run homestays with Konkani home cooking at the budget end, and beach resorts with dive desks at the top. Two full days covers the reef and the fort; three covers the backwaters too." },
    { "type": "h2", "text": "Frequently Asked Questions" },
    { "type": "h3", "text": "Do I need to know swimming for scuba diving at Tarkarli?" },
    { "type": "p", "text": "No. Instructors give you a shallow-water training session first and stay with you for the entire dive. Non-swimmers dive at Tarkarli every day of the season." },
    { "type": "h3", "text": "What is the best month for diving at Tarkarli?" },
    { "type": "p", "text": "October to December offers the clearest water and calmest seas. The season runs through May, but visibility is generally best in the post-monsoon months." },
    { "type": "h3", "text": "How much does scuba diving cost at Tarkarli?" },
    { "type": "p", "text": "Introductory dives are affordably priced for a single session including training, equipment and the instructor — confirm exactly what is included before paying, as operator pricing varies by season. Most first-timers pair the dive with a snorkel session the same day." },
    { "type": "h3", "text": "Can I visit Sindhudurg Fort and dive on the same day?" },
    { "type": "p", "text": "Yes — that is the classic Malvan day. Dive in the morning (slots start around 9:30 AM), have lunch in Malvan town, and take the afternoon boat to the fort." },
    { "type": "h3", "text": "Is Tarkarli open during the monsoon?" },
    { "type": "p", "text": "Effectively no. Diving and snorkelling shut down from June to September, and the Sindhudurg Fort boat trips also stop when the sea is rough." }
  ],
  "st-marys-island-udupi-day-trip": [
    { "type": "p", "text": "Six kilometres off the Karnataka coast, a small island rises out of the Arabian Sea made almost entirely of hexagonal rock columns — some standing in perfect honeycomb walls, others scattered like a giant's building blocks. St Mary's Island, off Malpe near Udupi, is India's most striking geological oddity you have probably never heard of: an 88-million-year-old volcanic formation that looks designed rather than erupted." },
    { "type": "h2", "text": "The geology: why the columns exist" },
    { "type": "p", "text": "The columns are basaltic lava formations — when thick lava flows cool and contract, they crack into polygonal columns, and here the geometry came out almost impossibly regular. The formations were declared a National Geological Monument by the Geological Survey of India in 1979. The group is actually four small islands, of which the northernmost carries the famous column formations. The Portuguese landed here in 1498 and named it after Mary — locals also call it Coconut Island or Thonsepar. Outlook Traveller's [St Mary's Island feature](https://www.outlooktraveller.com/experiences/nature/explore-the-lesser-known-st-marys-island-of-udupi-in-karnataka) captures the surreal first sight of the columns rising from the surf." },
    { "type": "h2", "text": "The ferry: timings, tickets and the weather reality" },
    { "type": "p", "text": "The island is reached only by boat from Malpe Beach, a 25–30 minute ride. The boating office at Malpe operates daily from roughly 9 AM to 5 PM in season, and return tickets are inexpensive, with a reduced fare for children — cash and UPI both work at the counter, and online booking is rarely available, so arrive early on weekends to avoid the queue. Small boats carry 12–14 people, while larger ferries depart once they fill. The hard truth: ferries run only from about September/October to May. During the monsoon (June to September) the sea is too rough and services are suspended entirely. Even in season, sailings are weather-dependent — if the sea is choppy, boats do not go. Check conditions at the jetty before making the drive, and keep a buffer plan for Udupi town." },
    { "type": "h2", "text": "What to do on the island (and what not to)" },
    { "type": "p", "text": "Plan for 60–90 minutes on the island itself. Walk the basalt columns — the rocks are sharp and slippery, so wear sandals or sneakers with grip, not thin flip-flops — then wander the shell beach, which is carpeted with broken shells rather than fine sand. Photography is the main activity: mid-morning to early afternoon gives the tealest water. Now the important don'ts: this is not a swimming beach. Strong currents and jagged rock make swimming and diving off the rocks genuinely dangerous, and lifeguards enforce it. Carry your own snacks and water — there are limited stalls — take every wrapper back with you, and do not pocket shells or rock pieces." },
    { "type": "h2", "text": "Combining it with Udupi" },
    { "type": "p", "text": "St Mary's is a half-day; Udupi makes it a full one. Before the ferry, have breakfast in Udupi town — this is the birthplace of the Udupi restaurant empire, so the masala dosas and filter coffee are the real thing. After the island, visit the Sri Krishna Temple, Udupi's spiritual heart, and catch sunset at Kaup Beach with its century-old lighthouse. Malpe Beach itself is the mainland hub for parasailing, banana rides and jet skis, if you want water sports the island cannot offer. The Hindu's [report on the island's tourism pull](https://www.thehindu.com/news/cities/Mangalore/udupis-st-marys-island-a-major-crowd-puller/article18461214.ece/amp/) notes that weekend and holiday footfall can double — so a weekday visit is calmer." },
    { "type": "h2", "text": "How to reach and best time" },
    { "type": "p", "text": "The nearest railway station is Udupi, on the Konkan line; Malpe Beach is 6–10 km away, a 15–30 minute auto or cab ride. Mangalore International Airport is about 60 km south. The best visiting window is October to January — pleasant weather, the clearest water colour and regular ferry schedules. March to May is hot but the ferries still run; June to September, the island is effectively closed. A realistic plan: an inexpensive ferry ride, a short auto hop to Malpe, and 2.5–4 hours total including queues and island time." },
    { "type": "h2", "text": "A sample day-trip timeline" },
    { "type": "p", "text": "The island rewards an early start. Aim to reach Malpe jetty by 9:30–10 AM: buy your round-trip ticket, board the first or second ferry of the day, and you are on the island by 10:30. Spend the first hour at the basalt columns — morning light is the best photography, and the crowds thin out later — then swim and walk the southern cove. Pack a picnic or eat at the small snack shacks near the jetty side, and catch a return ferry by 1:30–2 PM, leaving the afternoon for Malpe beach itself and the Malpe fishing harbour, where the evening fish market is a spectacle in its own right." },
    { "type": "p", "text": "Pair the trip with Udupi's other draws if you have the full day: the Shri Krishna Matha and its Kanakana Kindi, the old city's temple lanes, and a banana-bun-and-filter-coffee stop at one of the town's legendary old restaurants. Udupi is also the origin of the Udupi restaurant cuisine served across India — eating a temple-town meals plate here, in its birthplace, is the correct way to close the day. The Outlook Traveller [feature on St Mary's Island](https://www.outlooktraveller.com/experiences/nature/explore-the-lesser-known-st-marys-island-of-udupi-in-karnataka) frames the island as exactly this kind of half-day anchor within a wider Udupi–Malpe trip, which is how it works best in practice." },
    { "type": "p", "text": "What to carry: water and snacks (the island has limited options), swimwear and a change of clothes, reef-safe sunscreen, a dry bag for your phone, and cash for the ferry tickets and small purchases. Wear footwear you can wade in — the landing is from the boat into shallow water in many conditions. The basalt rocks are sharp and slippery when wet, so take the column photographs from the stable platforms rather than climbing the formations; they are a protected geological monument, and chipping or defacing them is an offence. Leave no litter — the island's beauty is exactly as fragile as it looks." },
    { "type": "h2", "text": "Frequently Asked Questions" },
    { "type": "h3", "text": "Can I swim at St Mary's Island?" },
    { "type": "p", "text": "No — and you should not try. Strong currents, submerged rocks and jagged basalt make the water around the island dangerous for swimming, and there are no lifeguards on the island. Use Malpe Beach on the mainland for water activities instead — it has the lifeguards, the shacks and the calm surf the island deliberately lacks." },
    { "type": "h3", "text": "What are the ferry timings to St Mary's Island?" },
    { "type": "p", "text": "Boats typically run from about 9 AM to 5 PM daily during the October–May season. Timings are weather-dependent; services are suspended in the monsoon and on rough-sea days." },
    { "type": "h3", "text": "How much does the St Mary's Island ferry cost?" },
    { "type": "p", "text": "Return tickets are bought at the boating counter at Malpe Beach, with a reduced fare for children. Confirm the current fare at the counter, as it varies slightly by season — and arrive early on weekends, when the first boats fill fast." },
    { "type": "h3", "text": "Is St Mary's Island open in the monsoon?" },
    { "type": "p", "text": "No. Ferry services are suspended from June to September when the Arabian Sea is rough, and the island is effectively inaccessible in those months. October to January is the best and most reliable window — the sea is calmest, the light is clearest for photographs, and cancellations are rare." },
    { "type": "h3", "text": "How much time do I need for the trip?" },
    { "type": "p", "text": "Budget 2.5–4 hours: the queue and ticket purchase, the 25–30 minute boat ride each way, and 60–90 minutes on the island. Pair it with Udupi town for a full day." }
  ],
  "swaraj-dweep-havelock-ferry-planning-guide": [
    { "type": "p", "text": "Every Andaman itinerary lives or dies at the jetty. Swaraj Dweep — still widely called Havelock — is an hour and a half by sea from Port Blair (now officially Sri Vijaya Puram), and your choice of ferry decides whether you land at Radhanagar Beach by 9 AM or spend your first island day queuing at the terminal. This is the logistics-first guide: operators, booking order, and how the ferry shapes your island plan." },
    { "type": "h2", "text": "Government vs private ferries" },
    { "type": "p", "text": "Two systems serve the route. Government ferries run by the Directorate of Shipping Services (DSS) sail from Phoenix Bay Jetty, take 2–2.5 hours, and start from a budget-friendly fare — the budget option, but schedules are less predictable and berths are handled through the government's separate enquiry system. Private ferries — Makruzz, Nautika, Green Ocean and ITT Majestic — sail from Haddo Jetty, take 90 minutes to just over two hours, and cost more depending on the class you choose. For most travellers, private is worth the premium: reserved seats, air-conditioned cabins and a crossing fast enough to keep seasickness at bay. The detailed [Port Blair to Havelock ferry schedule and pricing breakdown](http://andamanferrytickets.com/port-blair-to-havelock-ferry/) is updated frequently and is the best single reference for current sailings." },
    { "type": "h2", "text": "Which operator to choose" },
    { "type": "p", "text": "Makruzz is widely rated the most reliable with the cleanest cabins and runs the most sailings — typically six a day in peak season at 90 minutes per crossing, with departures spread from 06:00 to 14:00. Nautika is the newest vessel, a 285-passenger twin-deck catamaran with royale and luxury classes, also scheduled at 90 minutes. Green Ocean is the most affordable of the private operators but takes 120–135 minutes. In peak season (October onward), the route ramps up to around a dozen sailings a day. Practical rule: book Makruzz or Nautika for the fastest, most comfortable crossing; book Green Ocean if price matters more than an hour of your day. Always check live inventory for your exact date — schedules shift with the season." },
    { "type": "h2", "text": "The booking order that avoids mistakes" },
    { "type": "p", "text": "Book before you book anything else on the island. Same-day tickets exist only if seats remain, which is rare from October to March — buy at least a day or two ahead, and weeks ahead for December–January. The safe sequence, laid out well by the [Andaman ferry planning guide](https://andaman.guide/ferry-port-blair-to-havelock-island/): fix your route and date first (Sri Vijaya Puram/Port Blair to Swaraj Dweep/Havelock are the same pair under old and new names), then open each operator's own date search and compare, choose a sailing time that protects your airport connection and your first useful island day, compare final totals including fees, read the ticket rules for jetty, reporting time and ID requirements, and save the final ticket offline — do not rely on mobile data at the terminal. Carry a valid photo ID, report 45–60 minutes before departure, and keep seasickness tablets handy if you are prone." },
    { "type": "h2", "text": "How the ferry choice shapes your island plan" },
    { "type": "p", "text": "Take the earliest sailing you can tolerate. An 06:00–08:00 departure lands you on Swaraj Dweep by 9:30 AM with the whole day ahead: Radhanagar Beach (Beach No. 7, a Blue Flag beach consistently rated among Asia's best) for the morning, lunch back near the jetty market, and Kalapathar Beach for sunset. Day two is for water — snorkelling and scuba at Elephant Beach, or a day trip across to Shaheed Dweep (Neil Island) for the natural bridge and Bharatpur Beach. The ferries also run the onward legs to Neil and back to Port Blair, so a 3–4 night Andaman circuit (Port Blair → Swaraj Dweep → Neil → Port Blair) is entirely ferry-planned. If the logistics feel like a lot, that is exactly what packaged trips solve — our Andaman tour package at ₹39,000 handles ferries, stays and transfers end to end. Questions about sailing dates? Message us on WhatsApp at +91 81711 58569 and we will help you pick the right crossing." },
    { "type": "h2", "text": "Costs, cash and connectivity notes" },
    { "type": "p", "text": "Economy private classes are the mid-range option, premium classes cost more, and government ferries are the cheapest way across — compare live fares when you book, as they shift with the season. From Havelock Jetty, most resorts are 5–20 minutes by taxi or auto — confirm a pickup with your property before you sail. ATMs on the island are limited and connectivity is patchy, so carry sufficient cash for transfers and small purchases, keep snacks and water in your day bag, and plan an early night on arrival day — the sea air earns it. You can compare live operator schedules on the [12go ferry booking page](https://12go.asia/en/ferry/port-blair/havelock-island) before committing." },
    { "type": "h2", "text": "Extending the circuit: Shaheed Dweep (Neil Island)" },
    { "type": "p", "text": "Most travellers pair Swaraj Dweep with Shaheed Dweep — Neil Island — a 30-minute ferry hop away, and the circuit is the real reason to get the ferry planning right. Neil is smaller, quieter and flatter: Bharatpur Beach for snorkelling and glass-bottom boats, the famous Natural Bridge rock formation, and Laxmanpur Beach for some of the Andamans' best sunsets. One night on Neil is enough for most itineraries, two if you want a full beach day with no agenda." },
    { "type": "p", "text": "The classic 4-night Andaman circuit runs Port Blair → Swaraj Dweep (2 nights) → Neil (1 night) → Port Blair, with the Cellular Jail light-and-sound show slotted into the first or last evening in the capital. Ferries between the islands follow the same operators and the same rules — book ahead in season, keep offline copies, report early. This is also where a packaged trip earns its keep: inter-island transfers are the part of Andaman planning most likely to go wrong, and our Andaman tour package at ₹39,000 is built around exactly this ferry circuit." },
    { "type": "p", "text": "Jetty-day practicalities: the sea between Port Blair and the islands can be choppy from June to September, so sit mid-ship and face forward if you are prone to seasickness, and take medication 30 minutes before boarding. Luggage is limited on most private ferries — pack a day bag for the crossing and confirm the checked-bag policy when you book. If your flight lands in Port Blair after 2 PM, do not plan a same-day ferry to Swaraj Dweep; stay the night near the airport and take the morning sailing. The Cellular Jail light-and-sound show runs in the evening and is the correct use of that forced overnight." },
    { "type": "h2", "text": "Frequently Asked Questions" },
    { "type": "h3", "text": "How far in advance should I book the Port Blair to Havelock ferry?" },
    { "type": "p", "text": "At least 1–2 days ahead in normal season and several weeks ahead for December–January, when sailings sell out. Same-day seats are rare in peak season." },
    { "type": "h3", "text": "Which is the best ferry to Havelock — Makruzz, Nautika or Green Ocean?" },
    { "type": "p", "text": "Makruzz is the most reliable with the most daily sailings at 90 minutes; Nautika is the newest and equally fast; Green Ocean is cheapest but takes 120–135 minutes. Pick speed and reliability with Makruzz/Nautika, or price with Green Ocean." },
    { "type": "h3", "text": "Where do the ferries depart from in Port Blair?" },
    { "type": "p", "text": "Private ferries depart from Haddo Jetty; government DSS ferries depart from Phoenix Bay Jetty. The departure jetty is printed on your ticket — confirm it, because they are different terminals." },
    { "type": "h3", "text": "Do I need ID for the Andaman ferry?" },
    { "type": "p", "text": "Yes — carry a valid photo ID for check-in, and report 45–60 minutes before departure. Check-in counters typically close 15 minutes before sailing." },
    { "type": "h3", "text": "Is Swaraj Dweep the same as Havelock Island?" },
    { "type": "p", "text": "Yes. Swaraj Dweep is the official renamed name; Havelock is what everyone — operators, hotels and travellers — still uses. Booking sites show both names for the same route." }
  ],
  "lucknow-food-trail-morning-to-night": [
    { "type": "p", "text": "Lucknow does not do fast food. The capital of Awadh runs on dum — slow-cooked, patient, precise — and a single day of eating here moves like a well-paced meal: light and sweet at dawn, regal at lunch, chaotic and joyful by night. This is the morning-to-night route through the old city's kebab lanes and the new city's chaat institutions, sequenced the way locals actually eat it." },
    { "type": "h2", "text": "Dawn: malai makkhan and the winter window" },
    { "type": "p", "text": "If you are in Lucknow between November and February, start before 8 AM in Chowk, the old city's beating heart. Winter mornings belong to malai makkhan — saffron-tinged clouds of churned milk froth, so light they dissolve on the tongue, sold only in the cold months and usually gone within a few hours. It is Lucknow's most seasonal food experience and the reason winter is the city's best eating season. Follow it with breakfast at Sharma Ji Ki Chai near Lalbagh: samosas, bun maska and thick milky chai in a shop that has fed generations of morning regulars." },
    { "type": "h2", "text": "Late morning to lunch: the biryani and nahari hours" },
    { "type": "p", "text": "By 11 AM, head to Idrees — Idris Ki Biryani — for Lucknow's most argued-over plate. Awadhi biryani is nothing like the fiery Hyderabadi version: light, fragrant rice with separate grains, tender meat, aroma rather than heat, cooked dum-style. It routinely sells out by evening, so lunch is the safe window. Then walk it off toward Chowk and Raheem's (Raheem Hotel), the old-city institution for nahari and kulcha — slow-simmered beef or mutton shank stew scooped up with soft kulcha, the dish Lucknowis defend with genuine passion. NDTV's [full-day Lucknow eating itinerary](https://food.ndtv.com/food-drinks/how-to-eat-like-a-local-in-lucknow-a-full-day-itinerary-11338690) sequences this exact midday arc and is worth a read before you go." },
    { "type": "h2", "text": "Evening: chaat o'clock in Hazratganj" },
    { "type": "p", "text": "As the day cools, the food geography shifts to Hazratganj, Lucknow's colonial-era shopping boulevard. Royal Cafe's basket chaat — tokri chaat, a crisp fried potato basket loaded with curd, chutneys, sev and spice — is the city's most famous evening snack: indulgent, messy and a complete contrast to Awadhi restraint. Moti Mahal, a short walk away, is the other chaat anchor — basket chaat here, jalebi-rabri there, and strong opinions everywhere about which is better. This is also the hour for a kulhad of thick chai and some window-shopping along Ganj's lit facades." },
    { "type": "h2", "text": "Night: the kebab finale" },
    { "type": "p", "text": "Dinner in Lucknow means one name: Tunday Kababi. The galouti kebab — finely minced meat, impossibly soft, spiced with a famously guarded blend — with ulte tawe ka paratha (the inverted-griddle flatbread) is the dish no visit is complete without. The original outlet in Chowk keeps old-city hours and old-city crowds; go with patience and an appetite. For a second-night or a deeper cut, locals point to the kakori kebabs and pasanda at old-city institutions around Aminabad. End the night the Lucknowi way: a malai paan at Ram Ashrey in Chowk — silky sheets of milk, dry fruits, silver leaf — the perfect full stop." },
    { "type": "h2", "text": "Planning the day: how to reach, when to go, what it costs" },
    { "type": "p", "text": "Lucknow is well connected — Chaudhary Charan Singh International Airport, and the Charbagh railway station on the main Delhi–Kolkata line. Come between October and March; winter (November–February) is the definitive eating season, when malai makkhan appears and the kebab grills work overtime. The old city is best done on foot or by cycle-rickshaw — the lanes around Chowk and Aminabad are too narrow for cars, which is part of the charm. A full day of serious eating across six to eight stops is very affordable — most individual plates cost little more than a cup of coffee. Carry cash for the old-city stalls, pace yourself (the trail is a marathon, not a sprint), and note that the legendary non-veg institutions cluster in the old city while Hazratganj handles your chaat-and-café evenings." },
    { "type": "h2", "text": "Second-day add-ons: Residency, Rumi Darwaza and the chikan markets" },
    { "type": "p", "text": "If the trail earns a second day, spend the morning at the Residency — the scarred, garden-walled ruins of the 1857 siege, one of India's most evocative colonial sites — and walk to the Rumi Darwaza, the 60-foot gateway that is Lucknow's signature monument. The old city's chikan embroidery markets around Hazratganj and Aminabad are the shopping counterpoint to the eating: hand-embroidered kurtas and sarees at a fraction of big-city prices, with bargaining expected and respected." },
    { "type": "p", "text": "The second day also unlocks the dishes the first day skipped: the kakori kebabs at the old-city shops around Aminabad, the shahi tukda and kulfi-falooda at Chowk's sweet houses, and a proper sit-down Awadhi dinner — murgh mussallam, pasanda, warqi parathas — at a heritage restaurant. Team-BHP's [epic two-day Lucknow food tour](https://www.team-bhp.com/news/two-day-epic-lucknow-food-tour-pov-hardcore-foodie) is written from exactly this two-day perspective and lists the second-day addresses the one-day trail has to leave out." },
    { "type": "p", "text": "Old-city eating etiquette, worth knowing: the legendary non-veg institutions are concentrated in Chowk and Aminabad and keep old-city hours — many close by late evening, and Friday afternoons can be quiet. Queues at Idrees and Tunday move fast but look intimidating; they are. Carry cash, because the best stalls do not take cards, and eat in the order the day dictates — heavy kebabs at night, not at noon, or the trail defeats you by 3 PM. Vegetarians should note that the chaat, sweets and thandai circuit is entirely separate from the kebab lanes, so mixed groups can split and reconvene at Hazratganj in the evening without anyone compromising." },
    { "type": "h2", "text": "Frequently Asked Questions" },
    { "type": "h3", "text": "What is the one dish I must not miss in Lucknow?" },
    { "type": "p", "text": "The galouti kebab at Tunday Kababi. It is the dish the city's food reputation rests on — melt-in-mouth minced meat with ulte tawe ka paratha, the inverted-griddle flatbread. Go to the original Chowk outlet for the full old-city experience, order the kakori kebab alongside if the queue allows, and finish with the malai paan at Ram Ashrey. One meal here explains Awadhi cuisine better than any cookbook." },
    { "type": "h3", "text": "When is malai makkhan available in Lucknow?" },
    { "type": "p", "text": "Only in the winter months, roughly November to February, and only in the early morning hours — it melts as the day warms up, so go before 8–9 AM. The Chowk vendors make it overnight from the previous evening's milk, and the best batches are usually gone within a couple of hours of sunrise. If you are visiting outside winter, the city's other sweet morning rituals — bun maska at Sharma Ji, jalebi-rabri in Hazratganj — fill the gap, but malai makkhan is the reason food travellers time their Lucknow trip for December and January." },
    { "type": "h3", "text": "How is Lucknowi biryani different from Hyderabadi biryani?" },
    { "type": "p", "text": "Lucknowi (Awadhi) biryani is delicate — fragrant, lightly spiced, dum-cooked with aroma over heat. Hyderabadi biryani is bolder and spicier. At Idrees, expect subtlety, and go at lunch before it sells out." },
    { "type": "h3", "text": "Can vegetarians do the Lucknow food trail?" },
    { "type": "p", "text": "Absolutely. The chaat circuit (basket chaat, golgappe, aloo tikki), malai makkhan, bun maska, jalebi-rabri and the sweets-and-thandai stops are all vegetarian, and Hazratganj's café lane is entirely veg-friendly. In the old city, the famous non-veg institutions sit in the same lanes as vegetarian sweet shops and chaat stalls, so mixed groups can eat side by side. Many vegetarian travellers report the chaat-and-sweets day as the highlight — Lucknow's vegetarian game is as serious as its kebab game." },
    { "type": "h3", "text": "Is one day enough for Lucknow's food?" },
    { "type": "p", "text": "One well-planned day covers the icons — malai makkhan, Idrees biryani, Raheem's nahari, basket chaat, Tunday kebabs. Two days lets you add Aminabad's deeper cuts and a second chaat evening without rushing." }
  ],
  "hyderabad-48-hour-food-guide": [
    { "type": "p", "text": "Hyderabad is India's most delicious argument. The city runs on two cuisines at once — the royal Hyderabadi court food of biryani, haleem and Irani chai, and the fiery Telugu food of the streets — and 48 hours is just enough to taste both. This is a sprint, not a stroll: every meal is planned, every gap between meals has a purpose, and you will leave understanding why no other Indian city inspires this kind of food loyalty." },
    { "type": "h2", "text": "Day 1 morning: Charminar and the Irani café ritual" },
    { "type": "p", "text": "Start at dawn near the Charminar with the city's defining breakfast: Irani chai and Osmania biscuits at Nimrah Café, right by the monument. The chai is strong, milky and poured from a height; the Osmania — a salty-sweet biscuit named for the last Nizam — is engineered for dunking. Café Niloufer at Lakdikapul is the other great Irani café morning, but Nimrah with the Charminar in view is the postcard. Walk off breakfast around the Charminar and Laad Bazaar, the bangle market, then climb the monument itself. Outlook Traveller's [culinary trail through Telangana](https://www.outlooktraveller.com/destinations/india/a-culinary-trail-through-telangana-from-hyderabadi-icons-to-street-side-favourites) — updated January 2026 — confirms Nimrah, Niloufer and Café Bahar as the essential Irani café stops." },
    { "type": "h2", "text": "Day 1 lunch: the biryani question" },
    { "type": "p", "text": "Hyderabadi biryani is dum pukht in the kacchi style — raw marinated meat layered with half-cooked basmati and slow-steamed, so the rice drinks the meat's juices. For lunch, the old city is the answer: Shadab, the legendary biryani house, does a deeply local, no-frills plate that Hyderabadis swear by, and the Choice Hotel in the old city is the connoisseur's pick for chicken biryani. Order the mirchi ka salan and raita on the side — they are not garnishes, they are half the dish. Pace yourself: a Hyderabadi biryani lunch is a commitment, not a snack." },
    { "type": "h2", "text": "Day 1 evening: haleem and the street hour" },
    { "type": "p", "text": "Evening is for haleem — the slow-cooked wheat, barley, lentil and meat porridge, pounded for seven-plus hours into silk, crowned with fried onions and ghee. During Ramzan it floods the streets; the rest of the year, Pista House, Shah Ghouse and Sarvi are the trusted names, with Shadab's Banjara Hills outpost doing year-round haleem too. Then hit the streets for the Telugu side: mirchi bajji (batter-fried chillies with tamarind chutney) at old-city stalls, and punugulu from a tiffin centre. The Siasat [48-hours in Hyderabad itinerary](https://www.siasat.com/charminar-to-biryani-how-to-spend-48-perfect-hours-in-hyderabad-3323209/) builds the same Charminar-to-biryani arc this guide follows." },
    { "type": "h2", "text": "Day 2: the new city and the dessert finish" },
    { "type": "p", "text": "Day two crosses the Musi. Breakfast at Café Bahar in Basheerbagh — biryani for breakfast is a legitimate Hyderabadi tradition, and Bahar's morning crowd proves it. Spend the middle of the day at Golconda Fort or the Salar Jung Museum (both earn the detour), then lunch at Bawarchi near RTC Cross Roads, the Secunderabad institution whose biryani has fed generations of students and office-goers. Paradise at Secunderabad is the famous name every visitor knows; Bawarchi is the one locals quietly prefer. End the 48 hours with desserts: qubani ka meetha (apricot pudding) and double ka meetha (bread pudding in saffron syrup) — Pista House and Hotel Nayab are the classic addresses — and one final Irani chai. You will board your train home smelling faintly of saffron. That is normal." },
    { "type": "h2", "text": "Planning: how to reach, when to go, what it costs" },
    { "type": "p", "text": "Hyderabad is a major rail and air hub — Rajiv Gandhi International Airport and Secunderabad Junction connect to Delhi, Mumbai and Bengaluru with ease. The best eating weather is October to February; avoid the May heat if you plan to walk the old city. The metro connects Secunderabad, MG Road and the new city efficiently, but the old city around Charminar is an auto-and-walking zone. Serious eating here is very affordable — biryani plates at the legends, Irani chai for the price of a bus ticket, and street snacks for pocket change. Ramzan (March 2026) turns the old city into a night-long haleem festival, but the 48-hour sprint works brilliantly year-round." },
    { "type": "h2", "text": "Beyond the icons: the Telugu side of the city" },
    { "type": "p", "text": "Hyderabad's royal food gets the fame, but the city's Telugu kitchens are the deeper cut. A proper Telugu meals plate — rice, pappu (dal), sambar, rasam, a gongura (sorrel leaf) preparation, avakaya (mango pickle) and a fried vegetable, finished with curd rice — is served at Rayalaseema Ruchulu and the city's old tiffin centres, and it is an entirely different cuisine from the biryani belt. Jonna rotte (sorghum flatbread) with natukodi (country chicken) curry is the rural-Telangana dish to ask for; the Chutneys chain does a reliable city version of the full thali for first-timers." },
    { "type": "p", "text": "The street-snack layer is worth a dedicated hour too: punugulu (crisp fermented-batter fritters) with ginger chutney at any tiffin centre, pesarattu (green-moong dosa) with upma filling at Ram Ki Bandi in Nampally — a cart that draws midnight crowds — and the mirchi bajji stalls of the old city. Plantrip's [Hyderabad street-food itineraries](https://plantrip.io/itinerary/983576) map the punugulu-to-pesarattu arc across the city's neighbourhoods, and confirm what locals will tell you: in Hyderabad, the food between the famous meals is half the trip." },
    { "type": "p", "text": "Build the old city into the plan, not just its food. The Charminar, the Mecca Masjid and the Chowmahalla Palace are all within walking distance of the biryani belt, and Laad Bazaar — the centuries-old bangle market beside the Charminar — is where you buy the lacquer bangles Hyderabad is famous for. Go in the morning for the monument and the Nimrah breakfast, return at dusk when the Charminar is floodlit and the haleem stalls fire up. The old city's lanes are dense and best navigated on foot with a data connection for maps; autos handle the longer hops to Banjara Hills and Jubilee Hills for the evening." },
    { "type": "h2", "text": "Frequently Asked Questions" },
    { "type": "h3", "text": "Which biryani is better — Paradise or Shadab or Bawarchi?" },
    { "type": "p", "text": "Paradise is the famous name; Shadab is the old-city local's pick; Bawarchi is the Secunderabad institution. Try one old-city (Shadab) and one new-city (Bawarchi) across your 48 hours and decide for yourself — that is the correct answer." },
    { "type": "h3", "text": "What is kacchi-style Hyderabadi biryani?" },
    { "type": "p", "text": "Raw marinated meat is layered with partially cooked basmati rice and slow-steamed (dum) so the rice absorbs the meat's juices. It is the defining technique of Hyderabadi biryani, distinct from Lucknow's pukki style where cooked meat meets cooked rice." },
    { "type": "h3", "text": "Is haleem available outside Ramzan?" },
    { "type": "p", "text": "Yes. While Ramzan is peak haleem season — the old city's night stalls during the fasting month are a festival in themselves — Pista House, Shah Ghouse, Sarvi and Shadab's Banjara Hills outlet serve it year-round in Hyderabad. Off-season haleem is the same slow-cooked preparation, just without the midnight street crowds, and it makes an excellent monsoon-evening meal." },
    { "type": "h3", "text": "What is Irani chai and where is it best?" },
    { "type": "p", "text": "Strong, milky tea brewed the Irani café way, served in small saucer-cups with Osmania biscuits for dunking. Nimrah Café by the Charminar and Café Niloufer at Lakdikapul are the two essential stops — Nimrah for the monument view, Niloufer for the old-city bustle. Order the chai 'cutting' style in the small glass if you want the full Irani café ritual, and do not skip the bun maska." },
    { "type": "h3", "text": "Is 2 days enough for Hyderabad's food?" },
    { "type": "p", "text": "For the icons — Charminar breakfast, two biryanis, haleem, Irani cafés and desserts — yes. The city rewards repeat visits; the Telugu thali circuit alone deserves a third day." }
  ],
  "amritsar-winter-food-trail": [
    { "type": "p", "text": "Come November, Amritsar stops being a city and becomes a kitchen. The mustard fields around Punjab turn the winter menu green and gold — sarson da saag, makki di roti, gajar ka halwa — and the old city's tandoors work harder than at any other time of year. With Guru Nanak Jayanti falling on November 24, 2026, the winter food trail below is timed for the season when Amritsar eats best." },
    { "type": "h2", "text": "Start at the Golden Temple: the langar as experience" },
    { "type": "p", "text": "No Amritsar food trail starts anywhere else. The Guru Ka Langar at the Golden Temple serves over 100,000 free meals a day — dal, roti, sabzi, and kheer on festival days — to everyone who sits in the pangat rows, regardless of who they are. Volunteers cook and serve around the clock; you sit on the floor, eat with your hands, and wash your own plate. It is the largest free kitchen in the world and, for many travellers, the most moving meal of the trip. Go early morning or late evening to avoid the longest queues, cover your head, and do not miss the kada prasad — the ghee-rich wheat halwa served at the sanctum." },
    { "type": "h2", "text": "The winter thali: sarson, makki and the old dhabas" },
    { "type": "p", "text": "Winter is the only season for the real thing: sarson da saag (slow-simmered mustard greens with bathua and spinach, finished with white butter) and makki di roti (hand-patted cornmeal flatbread), eaten October through March. The two old-city anchors are both verified institutions. Kesar Da Dhaba, founded in 1916 in Sheikhupura near Lahore and relocated to Amritsar after the 1947 Partition, sits in a narrow lane at Chowk Passian near the Town Hall — its dal makhani and phirni, served in earthen bowls, have reportedly fed everyone from Jawaharlal Nehru to Indira Gandhi. Bharawan Da Dhaba, running since 1912 near the Town Hall on Golden Temple Road, is the saag specialist — open roughly 7 AM to midnight, and very affordable for a full meal for two. Curly Tales' [winter food trail guide](https://curlytales.com/india/food/from-sarson-ka-saag-to-kulcha-best-winter-food-trails-in-amritsar/) documents both in detail and is the best current reference for the season." },
    { "type": "h2", "text": "Kulcha mornings and lassi afternoons" },
    { "type": "p", "text": "The Amritsari kulcha is a different species from Delhi's — blistered, layered, stuffed with aloo or paneer, crushed flat after the tandoor and drowned in butter, served with onion-heavy chole and imli-pudina chutney. All India Famous Kulcha on Maqbool Road does the classic morning shift (roughly 8 AM–2:30 PM); Kulcha Land on Ranjit Avenue is the evening institution. Mid-afternoon belongs to lassi: thick Punjabi lassi in a kulhar, sweet or salted, topped with malai — Gian di lassi near the Golden Temple is the famous name, and Kanha Sweets on Lawrence Road pairs giant-puri chhole with a lassi worth the trip alone. Travel and Leisure's [Amritsar food rundown](https://www.travelandleisureasia.com/sea/destinations/india/amritsar-tourist-places-explore-golden-temple-and-other-must-visit-sites/) covers the dhaba-and-lassi circuit well." },
    { "type": "h2", "text": "Evening: fish, jalebi and the Wagah run" },
    { "type": "p", "text": "Amritsari fish — river fish in a spiced besan batter, fried crisp — is the old city's great non-veg street snack; Makhan Fish & Chicken Corner is the much-cited address, but ask a local for the current best stall, as these shift. For dessert, the legendary Gurdas Ram jalebiwala fries jalebis to order — crisp, juicy, eaten hot off the kadhai. If you are doing the Wagah border ceremony (around 4:15 PM in winter, 30 km from the city), eat after you return: the ceremony ends near sunset, and a hot jalebi-and-lassi evening back in the old city is the correct recovery." },
    { "type": "h2", "text": "Planning: how to reach, when to go, what it costs" },
    { "type": "p", "text": "Amritsar is well connected — Sri Guru Ram Dass Jee International Airport, and the railway station on the main Delhi line (the Shatabdi does Delhi–Amritsar in about 6 hours). November to February is the definitive window: the saag season, the lassi weather, and Guru Nanak Jayanti on November 24, 2026, when the Golden Temple is at its most spectacular. Days are pleasant, nights drop toward single digits — carry a jacket. The old city around the temple is a walking zone; autos handle the rest. A day of serious eating is very affordable — dhaba meals and kulcha breakfasts cost little, and the langar, of course, is free." },
    { "type": "h2", "text": "Fitting food around the temple and the Wagah ceremony" },
    { "type": "p", "text": "The winter food trail works best when it is choreographed around the two immovable events. Morning: the Golden Temple at dawn (fewer crowds, the best light on the sarovar), langar breakfast, then the kulcha run on Maqbool Road. Midday: the saag-and-dal dhaba lunch near the Town Hall, a walk through the old city's bazaars, and the Partition Museum — housed in the Town Hall itself — for the history that explains half the food on your plate. By 3 PM, leave for Wagah: the border is about 30 km out, and the winter ceremony starts around 4:15 PM." },
    { "type": "p", "text": "Back in the city by 7 PM, the evening is the trail's reward: hot jalebis off the kadhai, a thick lassi, and a slow walk around the illuminated temple complex — the Golden Temple at night, reflected in the sarovar, is the single most beautiful sight in Punjab. The indiatimes [day-in-Amritsar food guide](https://www.indiatimes.com/culture/food/11-places-you-have-to-eat-at-in-amritsar-if-youre-visiting-for-a-day-233433.html) sequences a similar dawn-to-night arc and is a useful cross-check for timings. One warning: on Guru Nanak Jayanti itself (November 24, 2026), every restaurant queue in the city doubles — eat early, eat patiently, and let the langar carry one meal." },
    { "type": "p", "text": "Dhaba practicalities: Kesar Da Dhaba and Bharawan Da Dhaba do not take reservations — you walk in, take a table, and the thali arrives. Lunch between 12 and 2 PM is the peak crush; go at 11:30 or after 3 for a calmer meal. The phirni at Kesar, served set in earthen bowls, sells out on busy days, so order it with your meal rather than after. Both dhabas sit in the old city's narrow lanes near the Town Hall — autos know them, and the walk from the Golden Temple complex is about 15–20 minutes through the bazaar, which is half the experience." },
    { "type": "h2", "text": "Frequently Asked Questions" },
    { "type": "h3", "text": "When is Guru Nanak Jayanti in 2026?" },
    { "type": "p", "text": "November 24, 2026 (Tuesday), coinciding with Kartik Purnima. The Golden Temple sees its biggest crowds of the year, so book stays well ahead." },
    { "type": "h3", "text": "What is the best month for the Amritsar food trail?" },
    { "type": "p", "text": "November to February. Sarson da saag and makki di roti are winter dishes (October–March), and the November–February window adds the best weather and the Gurpurab festivities." },
    { "type": "h3", "text": "Is the Golden Temple langar really free?" },
    { "type": "p", "text": "Yes — completely free, open to all visitors regardless of religion, serving over 100,000 meals daily. You will be asked to cover your head and sit in the communal rows, and volunteers welcome help with serving and washing up — participating, even briefly, is part of the experience." },
    { "type": "h3", "text": "Where is the best Amritsari kulcha?" },
    { "type": "p", "text": "All India Famous Kulcha on Maqbool Road for the classic morning kulcha-chole (8 AM–2:30 PM), and Kulcha Land on Ranjit Avenue for the evening shift. Both serve the blistered, butter-drenched tandoor original." },
    { "type": "h3", "text": "Can I do Amritsar's food trail as a day trip from Delhi?" },
    { "type": "p", "text": "It is possible but rushed — the Shatabdi makes it a long day. One overnight stay lets you do the langar, a dhaba lunch, the Wagah ceremony and a jalebi evening without sprinting." }
  ],
  "indore-sarafa-night-food-itinerary": [
    { "type": "p", "text": "At 8 PM, Sarafa Bazaar sells gold. By 9 PM, it sells dinner. Every night in Indore, the jewellery market beside Rajwada Palace pulls its shutters down — and over a hundred food stalls roll into the same lanes, cooking until 2 AM. Sarafa is India's most famous night food market, and it rewards one thing above all: arriving hungry, early, and with a plan." },
    { "type": "h2", "text": "How the night market works" },
    { "type": "p", "text": "By day, Sarafa is a working sarafa (bullion) market. Around 8–9 PM the jewellers close, vendors set up in the vacated street, and the lane fills with smoke, light and crowds. The market runs daily until roughly 2 AM, with the illuminated seven-storey Rajwada Palace — the 18th-century Holkar seat — as its backdrop. One critical timing note from TripHobo's [Sarafa Bazaar guide](https://www.triphobo.com/places/indore-india/sarafa-bazar): while stalls stay open past midnight, the best dishes sell out by about 10 PM. Arrive by 9 PM. Everything here is vegetarian — the market's rule, not a suggestion — and the whole lane is walkable only on foot." },
    { "type": "h2", "text": "The sequencing: what to eat in what order" },
    { "type": "p", "text": "Work the lane like a tasting menu. Start with Joshi Ji's dahi bada — half the show is watching him flip the soft vadas through the air and season them with a flick of spice mix. Then bhutte ka kees at Joshi's or Sawariya's: grated corn cooked with milk and spices, a dish that barely exists outside Malwa. Follow with sabudana khichdi, then the khopra patties at Vijay Chaat House — crisp potato patties stuffed with spiced coconut, an Indore preparation documented since the 1960s. In winter, add garadu: deep-fried purple yam tossed in hot, tangy masala, available only in the cold months. The Travel and Tourism Times' [Malwa food-culture guide](https://thetravelandtourismtimes.com/anchor-story-indore-and-the-malwa-table-a-guide-to-madhya-pradesh-s-most-documented-food-culture/) — the most thorough English-language documentation of this cuisine — walks through each of these dishes and their origins." },
    { "type": "h2", "text": "Sweets, shikanji and the late-night round" },
    { "type": "p", "text": "Save the second hour for sweets: malpua, jalebi-rabdi and imarti from the mithai stalls. Then the Nagori shikanji at Nagori Sweets — forget everything the name suggests; this is not the lemon shikanji of the north but a thick, sweet, dry-fruit-loaded milk drink, and it is superb. Johnny Hot Dog's egg benjo (a bun-omelette Indore original) covers the eggetarian corner, and badam milk at Lakshminarayan Doodhwala is the classic wind-down. Curly Tales' [Sarafa night-market walkthrough](http://curlytales.com/indores-sarafa-night-market-the-majestic-chhatris-a-journey-through-history-and-flavour/) captures the lane's chaos and lists the current stall favourites." },
    { "type": "h2", "text": "Daytime counterpart: Chappan Dukan and the Malwa breakfast" },
    { "type": "p", "text": "Sarafa is the night; Chappan Dukan is the day. Indore's other great food street runs daylight hours, and it is where you eat the city's signature breakfast: poha-jalebi — flattened rice tossed with mustard seeds, curry leaves and the proprietary jeerawan spice blend, served with crisp fresh jalebis. It is available across hundreds of stalls from early morning and costs very little. Add dal bafla (Malwa's baked answer to dal baati, drowned in ghee) at lunch, and you have done the full Indore food day: poha-jalebi at dawn, Chappan at noon, Sarafa at night." },
    { "type": "h2", "text": "Planning: how to reach, when to go, what it costs" },
    { "type": "p", "text": "Indore is well connected — Devi Ahilya Bai Holkar Airport and Indore Junction on the main rail network, an easy overnight from Delhi or Mumbai. October to March is the comfortable season, and winter adds garadu to the Sarafa menu. The market sits in the old city near Rajwada; autos and cabs from anywhere in Indore know it. A full Sarafa evening is remarkably cheap even if you eat aggressively — street plates cost very little. Carry cash, wear walking shoes, go on a weekday if you dislike crowds, and remember the golden rule: 9 PM arrival, or the bhutte ka kees is gone." },
    { "type": "h2", "text": "The breakfast that built the reputation: poha-jalebi" },
    { "type": "p", "text": "Indore's food fame starts at dawn, not at night. Poha-jalebi is the city's standard breakfast — hundreds of stalls serve it from early morning: flattened rice tossed with mustard seeds, curry leaves, peanuts and the proprietary jeerawan spice blend, eaten alongside crisp, freshly fried jalebis. The sweet-savoury pairing sounds wrong until the first bite, after which it becomes the only correct breakfast. Chappan Dukan, the daytime food street, is the best place to eat it in the open, but any neighbourhood stall with a crowd is a safe bet." },
    { "type": "p", "text": "Lunch in Indore means dal bafla — Malwa's answer to Rajasthan's dal baati, but baked rather than fried, cracked open and drowned in ghee before the dal is poured in. It is the region's great comfort plate, served at the old city's traditional restaurants and at Chappan's daytime stalls alike. And the afternoon belongs to Rajwada itself: walk the palace, the old city's lanes and the Chhatri Bagh cenotaphs of the Holkar rulers before the jewellery shutters come down and the night market takes over. Dawn poha, noon bafla, midnight Sarafa — that is the full Indore day, and it is one of the best eating days in India." },
    { "type": "p", "text": "The old city around Rajwada rewards a slow afternoon walk. The palace's seven storeys — a mix of Maratha, Mughal and French styles — anchor a neighbourhood of old havelis, the Gopal Mandir and the Chhatri Bagh cenotaphs of the Holkar rulers a short walk away. This is also Indore's shopping quarter: Maheshwari and Chanderi sarees, silver jewellery and the street markets that feed off the palace crowds. Time it so you are back near Sarafa by 8:30 PM — watch the jewellery shutters come down and the food stalls roll in, and you will have seen the neighbourhood change costumes in real time." },
    { "type": "h2", "text": "Frequently Asked Questions" },
    { "type": "h3", "text": "What time does Sarafa Bazaar open?" },
    { "type": "p", "text": "Food stalls set up around 8–9 PM after the jewellery market closes and run until about 2 AM, daily — the transformation of the lane is worth watching in itself. Arrive by 9 PM: the best dishes sell out by 10 PM, and the 9-to-11 window has the full menu, the liveliest crowds and the easiest movement before the late-night crush." },
    { "type": "h3", "text": "Is Sarafa Bazaar vegetarian?" },
    { "type": "p", "text": "Yes — only vegetarian food is served at Sarafa. Egg preparations like the benjo at Johnny Hot Dog are the exception at the margins." },
    { "type": "h3", "text": "What is bhutte ka kees?" },
    { "type": "p", "text": "Grated corn cooked with milk, spices and tempering — a Malwa-region speciality that is hard to find outside Indore, where it is as standard as poha. The texture is soft and almost creamy, the flavour gently spiced rather than hot. Try it at Joshi's or Sawariya's stall in Sarafa, and eat it early in the evening — it is one of the first dishes to sell out." },
    { "type": "h3", "text": "What is the difference between Sarafa and Chappan Dukan?" },
    { "type": "p", "text": "Sarafa is the night market (9 PM–2 AM) in the old city near Rajwada; Chappan Dukan is the daytime food street. Do Chappan for poha-jalebi breakfast and Sarafa for the night feast." },
    { "type": "h3", "text": "Is one evening enough for Sarafa?" },
    { "type": "p", "text": "One focused evening covers the icons if you arrive by 9 PM — work the lane in order: dahi bada and bhutte ka kees first, khopra patties and sabudana khichdi in the middle, sweets and Nagori shikanji to finish. Food obsessives do two nights — one for the classic stalls, one for the newer experimental ones." }
  ],
  "kolkata-park-street-food-walk": [
    { "type": "p", "text": "Park Street is not a food street. It is a century of Calcutta compressed into two kilometres — Swiss tearooms, jazz-era restaurants, the birthplace of the kathi roll — and the only correct way to eat it is on foot, in order, from breakfast to nightcap. This is the half-day walking route through Kolkata's most storied eating mile." },
    { "type": "h2", "text": "Stop 1: breakfast at Flurys, 1927" },
    { "type": "p", "text": "Start at 9 AM at Flurys, the tearoom founded in 1927 by Swiss couple Joseph and Frieda Flury. The old-world room — all bentwood chairs and glass pastry cases — still does the classic English breakfast: scrambled eggs, sausages, toast and Darjeeling tea, plus the rum balls and pastries Kolkatans queue for. It is the gentlest possible entry into the walk, and the room itself is a museum of the city's cosmopolitan past. The Telegraph's [ultimate Kolkata food walk feature](https://www.telegraphindia.com/my-kolkata/food/londons-raastawala-on-an-ultimate-kolkata-food-walk-flurys-trincas-and-kusum-rolls-on-park-street-indian-coffee-house-and-nizams-near-new-market/cid/1998752) begins its own trail here, and the logic is sound: eat the lightest meal first." },
    { "type": "h2", "text": "Stop 2: Trincas and the jazz years" },
    { "type": "p", "text": "Walk across the street to Trincas, born from the Flury partnership's split and reborn under new ownership in 1959 as one of India's great live-music restaurants. This is where Usha Uthup made her debut in 1969, and where Park Street's 1960s floor-show era lives on in the decor. Order the English breakfast — it made a comeback here after a 62-year gap — or linger over Continental classics for a late brunch. In the 1950s–70s this whole stretch, from Mocambo to Blue Fox to Peter Cat, was India's great entertainment district; Trincas is the best-preserved room of that era." },
    { "type": "h2", "text": "Stop 3: the roll hour — Kusum Rolls and Nizam's" },
    { "type": "p", "text": "By noon, join the queue at Kusum Rolls, 21 Park Street. Since 1971 this tiny counter has defined the Kolkata roll: flaky paratha, egg, chicken or mutton, onions, lime and chilli, rolled in paper and eaten standing, open 11:30 AM to 11:30 PM. The prawn kathi roll is the connoisseur's order. Then take the detour the walk demands: Nizam's, near New Market, where the kathi roll was invented in 1932. The original is a study in restraint compared to Kusum's maximalism — eat both, pick a side, argue about it forever. That argument is the point of the walk." },
    { "type": "h2", "text": "Stop 4: the Coffee House detour and the evening institutions" },
    { "type": "p", "text": "A short detour to College Street brings you to the Indian Coffee House, the adda capital of Bengal — high ceilings, uniformed waiters, endless coffee and the famous mutton cutlet, where generations of poets and professors have argued over very cheap cups. Back on Park Street for the evening, the old institutions take over: Peter Cat for the chelo kebab (buttered rice, kebab, a fried egg — the dish the queue is for) and Mocambo for Continental classics in a room that has barely changed in fifty years. Curly Tales' [roundup of Kolkata's legendary eateries](https://curlytales.com/kolkatas-classics-that-will-never-fail-to-impress-check-out-these-legendary-eateries/) covers these Park Street anchors and their timings." },
    { "type": "h2", "text": "Planning the walk: route, timing and costs" },
    { "type": "p", "text": "The walk is genuinely walkable: Flurys to Trincas to Kusum Rolls are all on Park Street itself (officially Mother Teresa Sarani), with Nizam's a 10-minute hop toward New Market and the Coffee House a short taxi ride to College Street. Start at 9 AM, finish by 9 PM, and pace the eating — this is six stops, not a race. October to February is the season; Park Street in December, lit for Christmas, is Kolkata at its most cinematic. The full walk including a sit-down dinner is very affordable; the rolls and Coffee House segments cost almost nothing, the evening restaurants carry the bill. Park Street is well served by metro (Park Street and Maidan stations) and stays lively late — which is exactly when the walk should end." },
    { "type": "h2", "text": "The evening institutions: chelo kebab and the Continental room" },
    { "type": "p", "text": "Park Street's evening belongs to two rooms that have barely changed in half a century. Peter Cat, the beloved basement restaurant, is famous for one dish above all: the chelo kebab — saffron-buttered rice, seekh kebab, a fried egg on top, served sizzling. It is Kolkata's great comfort plate, and the queue outside on weekends is part of the ritual. Order the sizzler only if you have room; the chelo kebab is the reason you came." },
    { "type": "p", "text": "Across the street, Mocambo is the Continental survivor of the Park Street golden age — prawn cocktail, devilled crab, baked Alaska, served by waiters who have worked the room for decades. It is expensive by Kolkata standards and worth it once, for the time-capsule value alone. Between the two sits the Oxford Bookstore's Cha Bar, the civilised interlude: browse the shelves, drink a proper pot of Darjeeling, and rest your feet before the evening round. The TOI [Park Street nostalgia piece](https://timesofindia.indiatimes.com/city/kolkata/amar-para-park-street/articleshow/134318164.cms) captures why this stretch — 17 Park Street's The Park hotel opened in 1967, the bookstore dates to 1919 — still feels like the city's living room." },
    { "type": "p", "text": "The College Street detour deserves more than the Coffee House. The street is Asia's largest book market — hundreds of stalls selling everything from rare first editions to university textbooks by the kilo — and the walk from the Coffee House to the book stalls is the intellectual heart of the city. The Presidency University campus, the Sanskrit College and the century-old publishing houses all sit within a few blocks. Go in the afternoon between the roll hour and the evening restaurants; the Coffee House mutton cutlet tastes better after an hour of browsing, and you will need the walk anyway." },
    { "type": "h2", "text": "Frequently Asked Questions" },
    { "type": "h3", "text": "Where was the kathi roll invented?" },
    { "type": "p", "text": "At Nizam's near New Market, Kolkata, in 1932 — the story goes that the kebab-roll was invented to keep the fillings off British customers' hands. Kusum Rolls on Park Street (1971) popularised the modern street version with its flaky paratha and generous fillings. Eat at both on this walk: Nizam's for the original, Kusum's for the evolution." },
    { "type": "h3", "text": "How long does the Park Street food walk take?" },
    { "type": "p", "text": "A full half-day to evening: roughly 9 AM to 9 PM across six stops, which sounds long but includes long sit-down breaks at Flurys, the Coffee House and dinner. You can compress it to an afternoon, but the evening institutions (Peter Cat, Mocambo) deserve their slot — and Park Street after dark is half the experience." },
    { "type": "h3", "text": "What should I order at Flurys?" },
    { "type": "p", "text": "The English breakfast with Darjeeling tea for the full 1927 experience — eggs, sausages, toast in the old tearoom — plus a rum ball or pastry from the glass cases on your way out. Flurys' bakery counter is a Kolkatan institution in its own right, and the morning crowd is gentler than the afternoon one." },
    { "type": "h3", "text": "Is Park Street walkable for the whole route?" },
    { "type": "p", "text": "Yes — the core stops are all on Park Street itself. Nizam's (New Market) and the Indian Coffee House (College Street) are short taxi hops. The Park Street and Maidan metro stations anchor both ends." },
    { "type": "h3", "text": "What is the best time of year for the food walk?" },
    { "type": "p", "text": "October to February, when Kolkata's winter makes walking pleasant and the old restaurants are at their cosiest. December adds Christmas lights on Park Street — the city's prettiest month, when Flurys does its famous Christmas cakes and the whole street stays out late. Avoid May–June, when the heat makes a six-stop walking day genuinely punishing." }
  ],
  "varanasi-food-day-guide": [
    { "type": "p", "text": "In Banaras, the day is measured in food, not hours. Dawn belongs to kachori, winter mornings to malaiyo, afternoons to lassi, evenings to chaat — and the whole rhythm is set by the ghats, the temples and the aarti. This is a dawn-to-late-night eating day mapped to the old city's geography, lane by lane." },
    { "type": "h2", "text": "6 AM: kachori-sabzi at Thatheri Bazar" },
    { "type": "p", "text": "Be at Ram Bhandar in Thatheri Bazar by 6–6:30 AM. The kachori-sabzi here — crisp, dal-stuffed kachoris with spiced potato sabzi — is the city's defining breakfast, and the crucial window is before 9 AM, after which it becomes a queue rather than a ritual. Kachori Gali, on the Sindhia–Manikarnika side, runs the same morning circuit. Eat the jalebi hot, alongside — jalebi loses its point when it sits. The varanasi_insider project's [breakfast-to-late-night food trail](https://github.com/devabhinav/varanasi_insider/blob/HEAD/content/en/banaras-food-trail-breakfast-to-late-night.md) maps this exact dawn sequence, lane by lane, and is the most precise local reference for the old-city food geography." },
    { "type": "h2", "text": "Winter mornings: malaiyo, then chai" },
    { "type": "p", "text": "From November to February, the morning has a second act: malaiyo — saffron-infused milk froth, whipped overnight by the winter dew, served in kulhads with pistachios. It is available only on winter mornings and mostly gone or collapsed by 10–11 AM. Shree Ji Sweets in Chowk is the hidden-gem address; stalls in Thatheri Bazar and Vishwanath Gali sell it too. Follow with the city's other great morning drink: malai toast and crushing chai at Laxmi Chaiwala, a Banaras institution for the thick, creamy, utterly unhurried cup." },
    { "type": "h2", "text": "Late morning: the lassi hour" },
    { "type": "p", "text": "By 9–11 AM, walk to Kachori Gali for the Blue Lassi Shop — 92 years old, walls covered in travellers' photos, and a menu of 75-plus lassi varieties from saffron to blueberry to Oreo. Thick, sweet, served in kulhads, it is better as a dessert stop than a drink with breakfast: after a glass or two you will not have room for anything else. The afternoon reset is Pehelwan Lassi in Lanka — the thickest, creamiest lassi in the city, crowned with rabri — or a thandai at Badal Thandai. The lassi round is very affordable for two. Outlook Traveller's [Varanasi gastronomic trail](https://www.outlooktraveller.com/amp/story/experiences/food-and-drink/varanasi-a-gastronomic-trail) covers the Blue Lassi–Pehelwan axis and the tamatar chaat rivalry in one sweep." },
    { "type": "h2", "text": "Afternoon to evening: the chaat circuit and the aarti" },
    { "type": "p", "text": "From about 3 PM, the chaat shops take over. Kashi Chat Bhandar at Godowlia Chowk is the king of tamatar chaat — mashed spiced tomatoes with namkeen crunch, a dish that exists almost nowhere else — plus aloo tikki and palak papdi chaat; Deena Chaat Bhandar in Chowk is the loyalist's alternative. A complete chaat meal costs very little. Time the evening around the Ganga Aarti at Dashashwamedh Ghat — arrive by 6 PM for a good spot — then eat late the Banarasi way: litti and chaat in the Assi–Lanka belt, and finally a Banarasi paan at Keshav Tambul Bhandar, soft enough to melt in the mouth. The paan is the full stop; nothing follows it." },
    { "type": "h2", "text": "Planning the day: navigating the galis" },
    { "type": "p", "text": "Varanasi's old city is a maze of galis that cars cannot enter — park at the nearest lane mouth (Godowlia, Chowk) and walk. The food day above is sequenced geographically: Thatheri Bazar and Kachori Gali in the morning, Lanka at midday, Godowlia–Dashashwamedh in the evening, Assi at night. November to February is the season (malaiyo, pleasant walking weather, Dev Deepawali crowds in November). A full day of serious eating is famously cheap — street food here costs very little. Carry cash, keep the morning light (the lassi and chaat hours are the heavy ones), and remember: in Banaras, the food waits for no one after 9 AM." },
    { "type": "h2", "text": "The sweet trail: Banarasi mithai beyond jalebi" },
    { "type": "p", "text": "Varanasi's sweet shops deserve their own hour. Start with lavang latika at Shree Ji Sweets in Chowk — the clove-pinned pastry parcel stuffed with khoya, the city's signature mithai, crisp outside and melting within. Then the kesariya peda, saffron-flecked and dense, and the malai gilori — paan-shaped sweets of malai and dry fruit that look like the real paan and taste like dessert. The old city's mithai lanes around Thatheri Bazar and Chowk are dense with these shops; ask for the fresh batch, always." },
    { "type": "p", "text": "The evening sweet is different in character: rabri-jalebi at the Godowlia stalls, kulfi-falooda in the Assi lanes, and in winter, the return of malaiyo vendors near the ghats for one last kulhad before the night ends. Banaras sweets share the city's philosophy — rich, unhurried, and best eaten standing at the counter where they were made. The timesnownews [Varanasi foodie guide](https://www.timesnownews.com/lifestyle/food/news/varanasi-foodie-guide-city-bloggers-recommend-what-and-where-to-eat-in-varanasi-article-117030211), built from local bloggers' recommendations, lists the current sweet-shop favourites by neighbourhood and is worth checking before you go." },
    { "type": "p", "text": "Structure the temple visit around the food, not against it. The Kashi Vishwanath Temple and the new corridor draw the biggest crowds between 9 AM and noon — which is exactly the kachori and malaiyo window, so eat first and do darshan after 11, when the morning rush thins. Afternoon temple visits pair naturally with the lassi hour in Lanka, and the Dashashwamedh Aarti at sunset is the hinge the whole day swings on: chaat before, paan after. Non-Hindus cannot enter the inner sanctum, but the corridor, the ghats and the aarti are open to all, and the old city's rhythm is visible from the lanes regardless." },
    { "type": "h2", "text": "Frequently Asked Questions" },
    { "type": "h3", "text": "What is malaiyo and when is it available?" },
    { "type": "p", "text": "Malaiyo is a winter-only dessert of saffron-flavoured milk froth served in kulhads, available roughly November to February and only in the morning — most vendors sell out by 10–11 AM, and the froth itself collapses as the day warms. It is made overnight by churning milk exposed to the winter dew, a technique that only works in the cold months. Shree Ji Sweets in Chowk and the Thatheri Bazar stalls are the classic addresses; go before 8 AM for the freshest batch." },
    { "type": "h3", "text": "Where is the best kachori-sabzi in Varanasi?" },
    { "type": "p", "text": "Ram Bhandar in Thatheri Bazar is the benchmark — go between 6 and 8 AM, before the kachoris sell out and the queue becomes the main event. Kachori Gali near the Manikarnika side runs the same morning circuit. Order the jalebi alongside the kachori-sabzi; the hot-sweet, crisp-savoury pairing is the whole point of the Banaras breakfast." },
    { "type": "h3", "text": "What is tamatar chaat?" },
    { "type": "p", "text": "A Banaras original: mashed boiled tomatoes and potatoes spiced and topped with onions, chillies and crispy namkeen, served hot off the tawa. It barely exists outside Varanasi, which makes it the dish to prioritise. Kashi Chat Bhandar at Godowlia Chowk is the most famous address — go upstairs for a seat, order the palak papdi chaat alongside, and watch the tawa work." },
    { "type": "h3", "text": "How old is the Blue Lassi Shop?" },
    { "type": "p", "text": "About 92 years, in Kachori Gali — famous for its 75-plus lassi flavours, from saffron and pomegranate to chocolate Oreo, all served in earthen kulhads." },
    { "type": "h3", "text": "Can I combine the food trail with the Ganga Aarti?" },
    { "type": "p", "text": "Yes — that is the ideal structure. Eat through the day, reach Dashashwamedh Ghat by 6 PM for the aarti (earlier on weekends and festival days, when the ghats fill fast), then finish with late chaat, litti and paan in the Assi–Lanka belt. The aarti is the hinge of the day: everything before it builds appetite, everything after it is celebration." }
  ]
};
